        [.. CasoDeEjemplo().Matches(Ejemplos(prompt)).Select(caso => caso.Groups["cuerpo"].Value)];

    public static string[] Palabras(string texto) =>
        NormalizadorTexto.Normalizar(texto).Split(' ', StringSplitOptions.RemoveEmptyEntries);

